const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const app = express();
const upload = multer({ dest: '/var/www/public/uploads' });

app.post('/upload', upload.single('file'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  // Use the filename provided by the user directly
  const userFilename = req.body.filename || req.file.originalname;
  const uploadPath = path.join('/var/www/public/uploads', userFilename);

  // Copy the uploaded file to the user-specified location
  fs.copyFileSync(req.file.path, uploadPath);
  fs.unlinkSync(req.file.path);

  res.json({
    message: 'File uploaded successfully',
    filename: userFilename,
    path: uploadPath
  });
});

app.listen(3000, () => {
  console.log('CTF challenge server running on port 3000');
});
